CREATE TABLE IF NOT EXISTS `prodven_db`.`pedidos` (
  `id_pedido` CHAR(36) NOT NULL,
  `id_empresa` CHAR(36) NOT NULL,
  `id_cliente` CHAR(36) NOT NULL,
  `id_direccion` CHAR(36) NULL DEFAULT NULL,
  `id_promocion` CHAR(36) NULL DEFAULT NULL,
  `numero_pedido` VARCHAR(50) NOT NULL,
  `tipo_entrega` ENUM('domicilio', 'recogida', 'en_sitio') NOT NULL DEFAULT 'domicilio',
  `tipo_pago` ENUM('digital', 'contra_entrega', 'mixto') NOT NULL DEFAULT 'digital',
  `estado` ENUM('pendiente', 'confirmado', 'en_preparacion', 'en_camino', 'entregado', 'cancelado', 'reembolsado') NOT NULL DEFAULT 'pendiente',
  `subtotal` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `descuento` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `impuestos` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `costo_domicilio` DECIMAL(12,2) NOT NULL DEFAULT '0.00',
  `total` DECIMAL(12,2) NOT NULL,
  `notas` TEXT NULL DEFAULT NULL,
  `direccion_envio` TEXT NULL DEFAULT NULL,
  `latitud_entrega` DECIMAL(10,8) NULL DEFAULT NULL,
  `longitud_entrega` DECIMAL(11,8) NULL DEFAULT NULL,
  `fecha_pedido` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_confirmacion` DATETIME NULL DEFAULT NULL,
  `fecha_entrega_real` DATETIME NULL DEFAULT NULL,
  `creado_por` CHAR(36) NOT NULL,
  `activo` TINYINT(1) NOT NULL DEFAULT '1',
  `eliminado` TINYINT(1) NOT NULL DEFAULT '0',
  `fecha_creacion` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_pedido`),
  UNIQUE INDEX `numero_pedido` (`numero_pedido` ASC) VISIBLE,
  INDEX `fk_pedido_direccion` (`id_direccion` ASC) VISIBLE,
  INDEX `fk_pedido_promocion` (`id_promocion` ASC) VISIBLE,
  INDEX `fk_pedido_creado_por` (`creado_por` ASC) VISIBLE,
  INDEX `idx_pedido_empresa` (`id_empresa` ASC) VISIBLE,
  INDEX `idx_pedido_cliente` (`id_cliente` ASC) VISIBLE,
  INDEX `idx_pedido_estado` (`estado` ASC) VISIBLE,
  INDEX `idx_pedido_numero` (`numero_pedido` ASC) VISIBLE,
  INDEX `idx_pedido_fecha_estado_empresa` (`fecha_pedido` ASC, `estado` ASC, `id_empresa` ASC) VISIBLE,
  INDEX `idx_pedido_empresa_fecha` (`id_empresa` ASC, `fecha_pedido` ASC) VISIBLE,
  CONSTRAINT `fk_pedido_cliente`
    FOREIGN KEY (`id_cliente`)
    REFERENCES `prodven_db`.`clientes` (`id_cliente`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_creado_por`
    FOREIGN KEY (`creado_por`)
    REFERENCES `prodven_db`.`usuarios` (`id_usuario`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_direccion`
    FOREIGN KEY (`id_direccion`)
    REFERENCES `prodven_db`.`direcciones_cliente` (`id_direccion`)
    ON DELETE SET NULL
    ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_empresa`
    FOREIGN KEY (`id_empresa`)
    REFERENCES `prodven_db`.`empresas` (`id_empresa`)
    ON DELETE RESTRICT
    ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_promocion`
    FOREIGN KEY (`id_promocion`)
    REFERENCES `prodven_db`.`promociones` (`id_promocion`)
    ON DELETE SET NULL
    ON UPDATE CASCADE)
ENGINE = InnoDB
DEFAULT CHARACTER SET = utf8mb4
COLLATE = utf8mb4_unicode_ci;


