-- -----------------------------------------------------
-- procedure sp_limpiar_carritos_abandonados
-- -----------------------------------------------------

DELIMITER $$
USE `prodven_db`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_limpiar_carritos_abandonados`()
BEGIN
    UPDATE carrito
    SET estado = 'abandonado'
    WHERE estado = 'activo'
      AND fecha_actualizacion < DATE_SUB(NOW(), INTERVAL 7 DAY);
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_limpiar_reservas_expiradas
-- -----------------------------------------------------

DELIMITER $$
USE `prodven_db`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_limpiar_reservas_expiradas`()
BEGIN
    -- Primero marcar como expiradas
    UPDATE reservas_stock
    SET estado = 'expirada'
    WHERE estado = 'activa'
      AND fecha_expiracion < NOW();
    
    -- Devolver stock solo de reservas recién expiradas (última hora)
    -- para evitar procesar la misma reserva dos veces
    UPDATE productos p
    INNER JOIN reservas_stock r ON p.id_producto = r.id_producto
    SET p.cantidad_stock = p.cantidad_stock + r.cantidad
    WHERE r.estado = 'expirada'
      AND r.fecha_expiracion >= DATE_SUB(NOW(), INTERVAL 1 HOUR);
END$$

DELIMITER ;
USE `prodven_db`;

DELIMITER $$
USE `prodven_db`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `prodven_db`.`trg_actualizar_calificacion_promedio`
AFTER INSERT ON `prodven_db`.`resenas`
FOR EACH ROW
BEGIN
    DECLARE nuevo_promedio DECIMAL(3,2);
    DECLARE total_resenas INT;
    
    SELECT AVG(calificacion), COUNT(*)
    INTO nuevo_promedio, total_resenas
    FROM resenas
    WHERE id_producto = NEW.id_producto AND visible = 1 AND eliminado = 0;
    
    UPDATE productos
    SET calificacion_promedio = nuevo_promedio,
        total_resenas = total_resenas
    WHERE id_producto = NEW.id_producto;
END$$

USE `prodven_db`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `prodven_db`.`trg_actualizar_calificacion_update`
AFTER UPDATE ON `prodven_db`.`resenas`
FOR EACH ROW
BEGIN
    DECLARE nuevo_promedio DECIMAL(3,2);
    DECLARE total_resenas INT;
    
    IF OLD.visible != NEW.visible OR OLD.eliminado != NEW.eliminado OR OLD.calificacion != NEW.calificacion THEN
        SELECT AVG(calificacion), COUNT(*)
        INTO nuevo_promedio, total_resenas
        FROM resenas
        WHERE id_producto = NEW.id_producto AND visible = 1 AND eliminado = 0;
        
        UPDATE productos
        SET calificacion_promedio = nuevo_promedio,
            total_resenas = total_resenas
        WHERE id_producto = NEW.id_producto;
    END IF;
END$$


DELIMITER ;

